import { parseCapture } from './capture-parser.mjs';
import { habitCalendar, habitStats } from './habits.mjs';
(() => {
'use strict';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const localDate=(s)=>s?new Date(`${s}T12:00:00`):null;
const fmtDate=(s,opts={month:'short',day:'numeric'})=>s?localDate(s).toLocaleDateString('en-US',opts):'No date';
const money=n=>`Rs ${Number(n||0).toLocaleString('en-LK',{maximumFractionDigits:2})}`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=o=>structuredClone(o);
const defaults={version:1,draftText:'',settings:{name:'there',budget:15000,calendarClientId:'258004480200-4s9gu43as0qctbjt3camklg4tvbarnan.apps.googleusercontent.com',calendarId:'primary',lowEnergy:false},modules:[],assignments:[],sessions:[],transactions:[],health:[],habits:[],checkins:[],messages:[],plans:[],audit:[]};
let state=clone(defaults),page='today',timer={seconds:25*60,running:false,started:null,mode:'focus',moduleId:''},timerInterval=null,googleToken=null,googleTokenClient=null,toastTimer;
let authenticated=false,registrationOpen=false,currentUser=null,revision=0,saveQueue=Promise.resolve(),draftSaveTimer=null;
let calendarOffset=0,calendarSelected=today();
let selectedHabitId='';
async function api(path,method='GET',data){const response=await fetch(path,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const body=await response.json().catch(()=>({}));if(!response.ok)throw Error(body.error||`Request failed (${response.status})`);return body}
function persist(){const snapshot=clone(state);$('#save-status').textContent='Saving…';saveQueue=saveQueue.then(async()=>{const result=await api('/api/state','PUT',{revision,state:snapshot});revision=result.revision;$('#save-status').textContent='Saved to Aniro database'}).catch(error=>{$('#save-status').textContent='Save failed';toast(error.message)});return saveQueue}
async function boot(){try{const session=await api('/api/session');authenticated=session.authenticated;registrationOpen=session.registrationOpen;currentUser=session.user;if(authenticated){const data=await api('/api/state'),savedSettings=data.state.settings||{};state={...clone(defaults),...data.state,settings:{...defaults.settings,...savedSettings,calendarClientId:savedSettings.calendarClientId||defaults.settings.calendarClientId}};revision=data.revision;document.querySelector('.shell').classList.remove('auth-mode');render()}else renderAuth()}catch(error){renderAuth(error.message)}}
function renderAuth(message=''){document.querySelector('.shell').classList.add('auth-mode');$('#mobile-nav').innerHTML='';$('#app').innerHTML=`<section class="auth-panel"><div class="brand auth-brand"><span class="brand-mark">a<span class="brand-dot">.</span></span><div><strong>Aniro</strong><small>STUDENT LIFE OS</small></div></div><div class="kicker">PRIVATE STUDENT SPACE</div><h1>${registrationOpen?'Create your account':'Welcome back.'}</h1><p class="muted">${registrationOpen?'Set up the single account for this Aniro installation.':'Sign in to your personal workspace.'}</p>${message?`<p class="auth-error" role="alert">${esc(message)}</p>`:''}<form id="auth-form" class="stack">${registrationOpen?'<div class="field"><label for="auth-name">Display name</label><input id="auth-name" name="displayName" autocomplete="name" required maxlength="60"></div>':''}<div class="field"><label for="auth-username">Username</label><input id="auth-username" name="username" autocomplete="username" required minlength="3" maxlength="64"></div><div class="field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="${registrationOpen?'new-password':'current-password'}" required minlength="12"></div><button class="button lime full" type="submit">${registrationOpen?'Create account':'Sign in'} →</button></form><p class="activity auth-foot">Your records are stored in the app's SQLite database. Export backups from Settings.</p></section>`}
function commit(type,detail,fn){const before=clone({...state,audit:[]});fn();state.audit=[{id:uid(),at:new Date().toISOString(),type,detail,before}];persist();render();toast(`${detail} · Undo available`,true)}
function undo(){const last=state.audit[0];if(!last)return;state=last.before;persist();render();toast('Last change undone')}
function toast(message,undoable=false){const el=$('#toast');el.innerHTML=`${esc(message)}${undoable?' <button class="text-button" style="color:var(--lime)" data-action="undo">Undo</button>':''}`;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();const first=$('#modal-content input, #modal-content textarea, #modal-content select');first?.focus()}
function closeModal(){if($('#modal').open)$('#modal').close()}
const nav=[['today','Today','⌂'],['inbox','Inbox','✦'],['study','Study','◫'],['calendar','Calendar','▦'],['money','Money','◉'],['wellbeing','Wellbeing','♡'],['insights','Insights','▥'],['settings','Settings','⚙']];
function renderNav(){const item=([id,label,icon])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`;$('#desktop-nav').innerHTML=nav.map(item).join('');$('#mobile-nav').innerHTML=nav.filter(([id])=>['today','inbox','study','calendar','wellbeing'].includes(id)).map(item).join('')}
function setPage(next){page=next;render();scrollTo({top:0,behavior:'smooth'});$('#app').focus()}
function render(){renderNav();$('#breadcrumb').textContent=nav.find(n=>n[0]===page)?.[1]||'Today';$('#today-date').textContent=new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'});$('#offline-badge').hidden=navigator.onLine;const pages={today:renderToday,inbox:renderInbox,study:renderStudy,calendar:renderCalendar,money:renderMoney,wellbeing:renderWellbeing,insights:renderInsights,settings:renderSettingsFull};$('#app').innerHTML=(pages[page]||renderToday)();}
function header(kicker,title,sub,action=''){return `<div class="page-header"><div><div class="kicker">${kicker}</div><h1>${title}</h1>${sub?`<p class="subhead">${sub}</p>`:''}</div>${action}</div>`}
function empty(title,detail){return `<div class="empty"><strong>${title}</strong>${detail}</div>`}
function allDeadlines(){return state.assignments.filter(a=>!['completed','submitted','archived'].includes(a.status)).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'))}
function dueTag(date){if(!date)return '<span class="tag">No due date</span>';const days=Math.ceil((localDate(date)-localDate(today()))/86400000);let cls=days<0?'danger':days<=2?'warn':'lime';let label=days<0?`${Math.abs(days)}d overdue`:days===0?'Due today':days===1?'Tomorrow':`Due ${fmtDate(date)}`;return `<span class="tag ${cls}">${label}</span>`}
function moduleName(id){return state.modules.find(m=>m.id===id)?.name||'General'}
function monthTransactions(){return state.transactions.filter(t=>t.date?.startsWith(today().slice(0,7)))}
function spent(){return monthTransactions().filter(t=>t.type==='expense').reduce((s,t)=>s+Number(t.amount),0)}
function weeklyMinutes(){const start=new Date();start.setDate(start.getDate()-6);return state.sessions.filter(s=>localDate(s.date)>=localDate(start.toISOString().slice(0,10))).reduce((sum,s)=>sum+Number(s.minutes),0)}
function renderHabitSection(full=false){const habits=state.habits;const checked=new Set(state.checkins.filter(c=>c.date===today()).map(c=>c.habitId));const selected=habits.find(h=>h.id===selectedHabitId)||habits[0];if(selected)selectedHabitId=selected.id;const rows=habits.map(h=>`<div class="habit-row"><div class="habit-row-copy"><strong>${esc(h.name)}</strong><small>${esc(h.cue||'Any time today')}</small></div><button type="button" class="habit-toggle ${checked.has(h.id)?'is-done':''}" data-action="toggle-habit-date" data-id="${esc(h.id)}" data-date="${today()}" aria-pressed="${checked.has(h.id)}" aria-label="${checked.has(h.id)?'Undo':'Mark'} ${esc(h.name)} for today">${checked.has(h.id)?'Done ✓':'Mark today'}</button>${full?`<button type="button" class="habit-edit" data-action="edit-habit" data-id="${esc(h.id)}" aria-label="Edit ${esc(h.name)}">Edit</button>`:''}</div>`).join('');const stats=selected?habitStats(state.checkins,selected.id):null;const days=selected?habitCalendar(state.checkins,selected.id):[];return `<section class="habit-panel" aria-labelledby="habits-heading"><div class="habit-heading"><div><span class="kicker">A LITTLE, OFTEN</span><h2 id="habits-heading">${full?'Your habits':'Habits today'}</h2><p class="muted">One tap to record today. Missed days are just empty days.</p></div>${!full&&habits.length?'<button class="text-button" data-page="wellbeing">Activity map →</button>':''}</div>${habits.length?`<div class="habit-list">${rows}</div>`:'<div class="habit-empty">No habits yet. Start with one small action you want to notice.</div>'}<form id="quick-habit-form" class="habit-add"><label for="quick-habit-name">Add a habit</label><div><input id="quick-habit-name" name="habitName" maxlength="60" required placeholder="e.g. Read for 10 minutes" autocomplete="off"><button class="button lime" type="submit">Add habit</button></div></form>${full&&selected?`<div class="heatmap-panel"><div class="heatmap-heading"><div><span class="meta">LAST 13 WEEKS</span><h3>Activity map</h3><p>${stats.last7} of the last 7 days checked in${stats.run>=2?` · ${stats.run}-day run`:''}</p></div><div class="field"><label for="habit-map-select">Show habit</label><select id="habit-map-select">${habits.map(h=>`<option value="${esc(h.id)}" ${h.id===selected.id?'selected':''}>${esc(h.name)}</option>`).join('')}</select></div></div><div class="heatmap-scroll"><div class="heatmap-layout"><div class="heatmap-weekdays" aria-hidden="true"><span>Sun</span><span></span><span>Tue</span><span></span><span>Thu</span><span></span><span>Sat</span></div><div class="heatmap-grid" role="group" aria-label="${esc(selected.name)} activity over 13 weeks">${days.map(day=>`<button type="button" class="heatmap-day ${day.active?'is-done':''} ${day.today?'is-today':''}" data-action="toggle-habit-date" data-id="${esc(selected.id)}" data-date="${day.date}" aria-label="${esc(selected.name)}, ${localDate(day.date).toDateString()}: ${day.active?'done':'not checked'}" aria-pressed="${day.active}" ${day.future?'disabled':''}></button>`).join('')}</div></div></div><p class="heatmap-help">Select a square to add or undo a past check-in. Today is outlined.</p></div>`:''}</section>`}
function renderToday(){const pending=allDeadlines();const priorities=pending.slice(0,3);const first=priorities[0];const recent=state.messages.slice(0,2);if(state.settings.lowEnergy)return `${header('YOUR SPACE',`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(state.settings.name)}.`,"One small step is enough today.")}<section class="hero"><div class="hero-copy"><div class="kicker" style="color:#394E14">LOW-ENERGY VIEW</div><h1>Start where<br>you are<span style="color:#6C8F20">.</span></h1><p>Capture a thought or take ten minutes to focus. The rest can wait.</p><div class="row-wrap"><button class="button" data-page="inbox">✦ &nbsp; Quick capture</button><button class="button ghost" data-action="open-timer">10-minute focus</button></div></div><div class="hero-art" aria-hidden="true"></div></section><section class="card" style="margin-top:18px"><span class="meta">ONE THING TO KNOW</span>${first?`<h2 style="margin-top:14px">${esc(first.title)}</h2><p>${esc(moduleName(first.moduleId))}</p>${dueTag(first.due)}`:empty('No urgent deadline','You can take a breath.')}</section>${renderHabitSection()}<button class="text-button" data-action="toggle-low-energy" style="margin-top:15px">Show full dashboard</button>`;return `${header('YOUR SPACE',`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(state.settings.name)}.`,"A calm view of what matters today.")}
<section class="hero"><div class="hero-copy"><div class="kicker" style="color:#394E14">ONE PLACE FOR THE WHOLE DAY</div><h1>Make room for<br>what matters<span style="color:#6C8F20">.</span></h1><p>Drop a thought, a deadline, a study session, or an expense. Aniro will help sort it out.</p><button class="button" data-page="inbox">✦ &nbsp; Tell Aniro about today</button></div><div class="hero-art" aria-hidden="true"></div></section>${renderHabitSection()}
<div class="section-title"><h2>Your day at a glance</h2><span class="meta">${fmtDate(today(),{weekday:'long',month:'long',day:'numeric'})}</span></div>
<div class="grid three"><section class="card"><span class="meta">UP NEXT</span>${first?`<div class="stat-number" style="font-size:1.5rem;line-height:1.1;margin-top:19px">${esc(first.title)}</div><p class="muted">${esc(moduleName(first.moduleId))}</p>${dueTag(first.due)}`:empty('Nothing pressing','Add an assignment to see your next deadline.')}</section><section class="card dark"><span class="meta">STUDY THIS WEEK</span><div class="stat-number">${Math.round(weeklyMinutes()/60*10)/10}<span style="font-size:1rem"> hrs</span></div><p>Every session counts. A small one is enough to begin.</p><button class="button small lime" data-action="open-timer">Start a focus session ↗</button></section><section class="card"><span class="meta">MONTHLY SPENDING</span><div class="stat-number">${money(spent())}</div><p class="muted">of ${money(state.settings.budget)} budget</p><div class="progress"><span style="width:${Math.min(100,Math.round(spent()/Math.max(1,state.settings.budget)*100))}%"></span></div></section></div>
<div class="grid two" style="margin-top:18px"><section class="card"><div class="row"><h2>Top priorities</h2><button class="text-button" data-page="study">View study</button></div>${priorities.length?priorities.map((a,i)=>`<div class="list-row"><div class="row-wrap"><span class="meta" style="min-width:18px">0${i+1}</span><div><strong>${esc(a.title)}</strong><small>${esc(moduleName(a.moduleId))}</small></div></div>${dueTag(a.due)}</div>`).join(''):empty('A clear slate','Your upcoming work will appear here.')}</section><section class="card"><div class="row"><h2>Recent captures</h2><button class="text-button" data-page="inbox">Open inbox</button></div>${recent.length?recent.map(m=>`<div class="list-row"><div><strong>${esc(m.text.slice(0,68))}${m.text.length>68?'…':''}</strong><small>${fmtDate(m.date)}</small></div><span class="tag ${m.status==='reviewed'?'lime':''}">${esc(m.status)}</span></div>`).join(''):empty('Your inbox is ready','Write naturally. Aniro will suggest updates for review.')}</section></div>`}
function renderInbox(){return `${header('CAPTURE & REVIEW','Your inbox','Write the way you think. Review each suggested update before anything is saved.')}<section class="capture-box"><div class="kicker">TELL ANIRO ABOUT TODAY</div><textarea id="capture-text" maxlength="5000" placeholder="I studied networking for 45 minutes, spent Rs 200 on lunch, and my database assignment is due Friday...">${esc(state.draftText||'')}</textarea><div class="capture-footer"><span class="activity">Dates, expenses, study time, tasks, and notes</span><div class="row-wrap"><button class="button ghost" data-action="parse-capture-ai" title="Sends this note to Google Gemini when a server key is configured">Review with AI</button><button class="button lime" data-action="parse-capture">Review locally →</button></div></div><p class="activity" style="margin:10px 0 0">Local review stays on this device. AI review sends this note to Google only when you choose it; nothing is saved until you approve.</p></section><div id="proposal-area"></div><div class="section-title"><h2>Capture history</h2><span class="meta">${state.messages.length} ENTRIES</span></div><section class="card">${state.messages.length?state.messages.map(m=>`<div class="list-row"><div><strong>${esc(m.text)}</strong><small>${fmtDate(m.date)} · ${m.approved||0} approved update${m.approved===1?'':'s'}</small></div><span class="tag ${m.status==='reviewed'?'lime':''}">${esc(m.status)}</span></div>`).join(''):empty('No captures yet','Your messages and their reviewed results will appear here.')}</section>`}
function renderStudyBase(){const due=allDeadlines(),sessions=state.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `${header('ACADEMIC WORKSPACE','Study, one step at a time','Your modules, deadlines, and focus sessions in one clear view.',`<button class="button lime" data-action="add-assignment">+ Add assignment</button>`)}<div class="row-wrap" style="margin-bottom:20px"><button class="button small ghost" data-action="add-module">+ Add module</button><button class="button small ghost" data-action="open-timer">◷ Focus timer</button><button class="button small ghost" data-action="plan-session">+ Plan session</button></div><div class="section-title"><h2>Upcoming work</h2><span class="meta">${due.length} OPEN</span></div><section class="card">${due.length?due.map(a=>`<div class="list-row"><div><strong>${esc(a.title)}</strong><small>${esc(moduleName(a.moduleId))} · ${esc(a.kind||'Assignment')} · ${esc(a.status||'not started')}</small></div><div class="row-wrap">${dueTag(a.due)}<button class="button small ghost" data-action="edit-assignment" data-id="${a.id}">Edit</button><button class="mini-actions" style="border:0;background:none" data-action="complete-assignment" data-id="${a.id}" title="Complete">✓</button></div></div>`).join(''):empty('No deadlines yet','Add an assignment or exam to start planning.')}</section><div class="section-title"><h2>Your modules</h2><span class="meta">${state.modules.length} TOTAL</span></div><div class="grid three">${state.modules.length?state.modules.map(m=>`<section class="card module-card"><div class="row"><span class="meta">${esc(m.code||'MODULE')}</span><button class="text-button" data-action="edit-module" data-id="${m.id}">Edit</button></div><h3>${esc(m.name)}</h3><p class="muted" style="font-size:13px">${esc(m.type||'Concept-heavy')} · ${state.sessions.filter(s=>s.moduleId===m.id).reduce((n,s)=>n+Number(s.minutes),0)} min studied</p><span class="tag">Confidence ${esc(m.confidence||3)}/5</span></section>`).join(''):empty('Start with one module','Adding a module makes your study tracking more useful.')}</div><div class="section-title"><h2>Recent focus sessions</h2><button class="text-button" data-page="insights">See insights</button></div><section class="card">${sessions.length?sessions.map(s=>`<div class="list-row"><div><strong>${esc(moduleName(s.moduleId))}</strong><small>${fmtDate(s.date)} · ${esc(s.note||'Focused study')}</small></div><span class="tag lime">${s.minutes} min</span></div>`).join(''):empty('No sessions logged','Use the focus timer or log a session from your inbox.')}</section>`}
function strategy(type){return ({'Memory-heavy':'Active recall and spaced review','Practice-heavy':'Worked problems and an error log','Concept-heavy':'Explain a concept from memory','Project-heavy':'Move one milestone forward'})[type]||'Review one small topic'}
function renderStudy(){return `${renderStudyBase()}<div class="section-title"><h2>Suggested next sessions</h2><span class="meta">BASED ON MODULE TYPE</span></div><div class="grid two">${state.modules.length?state.modules.map(m=>{const next=allDeadlines().find(a=>a.moduleId===m.id);const minutes=Number(m.confidence)<=2?15:25;return `<section class="card"><div class="row start"><div><span class="meta">${esc(m.type||'MODULE')}</span><h3 style="margin:9px 0">${esc(m.name)}</h3></div>${next?dueTag(next.due):'<span class="tag">No deadline</span>'}</div><p class="muted">${esc(strategy(m.type))}. ${next?`Work toward ${esc(next.title)}.`:'Choose one topic to move forward.'}</p><button class="button small lime" data-action="suggest-plan" data-id="${m.id}">Plan ${minutes} minutes →</button></section>`}).join(''):empty('Suggestions appear with modules','Add a module and its learning type to get a focused next step.')}</div>`}
function renderMoney(){const tx=state.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date));const incomes=monthTransactions().filter(t=>t.type==='income').reduce((s,t)=>s+Number(t.amount),0);const categories={};monthTransactions().filter(t=>t.type==='expense').forEach(t=>categories[t.category]=(categories[t.category]||0)+Number(t.amount));return `${header('MONEY, WITHOUT THE FRICTION','Money overview','A simple picture of where your money went.',`<button class="button lime" data-action="add-transaction">+ Log transaction</button>`)}<div class="grid three"><section class="card"><span class="meta">SPENT THIS MONTH</span><div class="stat-number">${money(spent())}</div><p class="muted">${Math.round(spent()/Math.max(1,state.settings.budget)*100)}% of monthly budget</p><div class="progress"><span style="width:${Math.min(100,Math.round(spent()/Math.max(1,state.settings.budget)*100))}%"></span></div></section><section class="card"><span class="meta">MONTHLY BUDGET</span><div class="stat-number">${money(state.settings.budget)}</div><button class="text-button" data-action="edit-budget">Adjust budget</button></section><section class="card dark"><span class="meta">REMAINING</span><div class="stat-number">${money(Math.max(0,Number(state.settings.budget)-spent()))}</div><p class="muted" style="color:#B9C0B3">Income recorded this month: ${money(incomes)}</p></section></div><div class="grid two" style="margin-top:18px"><section class="card"><h2>By category</h2>${Object.keys(categories).length?Object.entries(categories).sort((a,b)=>b[1]-a[1]).map(([category,value])=>`<div style="margin:20px 0"><div class="row"><strong>${esc(category)}</strong><span>${money(value)}</span></div><div class="progress" style="margin-top:8px"><span style="width:${Math.round(value/Math.max(spent(),1)*100)}%"></span></div></div>`).join(''):empty('Nothing to chart yet','Log an expense to see your categories.')}</section><section class="card"><div class="row"><h2>Transactions</h2><span class="meta">${tx.length} TOTAL</span></div>${tx.length?tx.map(t=>`<div class="list-row"><div><strong>${esc(t.note||t.category)}</strong><small>${esc(t.category)} · ${fmtDate(t.date)}</small></div><div class="row-wrap"><strong style="color:${t.type==='income'?'#598224':'var(--ink)'}">${t.type==='income'?'+':'−'}${money(t.amount)}</strong><button class="text-button" data-action="edit-transaction" data-id="${t.id}">Edit</button></div></div>`).join(''):empty('No transactions','Quick logs will appear here.')}</section></div>`}
function renderWellbeing(){const current=state.health.filter(h=>h.date===today());return `${header('GENTLE TRACKING','Wellbeing','Track what helps. A blank day is not a failure.',`<button class="button lime" data-action="add-health">+ Add a note</button>`)}${renderHabitSection(true)}<div class="section-title"><h2>Other notes</h2><span class="meta">${current.length} TODAY</span></div><div class="grid two"><section class="card">${current.length?current.map(h=>`<div class="list-row"><div><strong>${esc(h.kind)}</strong><small>${esc(h.note||h.value)}</small></div><button class="text-button" data-action="edit-health" data-id="${h.id}">Edit</button></div>`).join(''):empty('Nothing logged today','Sleep, mood, movement, meals, or anything useful.')}</section><section class="card lime-card"><div class="kicker" style="color:#5D7D23">LOW ENERGY IS STILL PROGRESS</div><h2>Make the next step tiny.</h2><p>Two minutes of reading or a glass of water counts. You can pause tracking whenever you like.</p><button class="button small" data-action="toggle-low-energy">${state.settings.lowEnergy?'Turn off':'Turn on'} low-energy mode</button></section></div>`}
function renderInsights(){const byModule={};state.sessions.forEach(s=>byModule[moduleName(s.moduleId)]=(byModule[moduleName(s.moduleId)]||0)+Number(s.minutes));const txCats={};state.transactions.filter(t=>t.type==='expense').forEach(t=>txCats[t.category]=(txCats[t.category]||0)+Number(t.amount));const days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(6-i));return d.toISOString().slice(0,10)});const vals=days.map(d=>state.sessions.filter(s=>s.date===d).reduce((n,s)=>n+Number(s.minutes),0));const max=Math.max(60,...vals);return `${header('A CLEARER PICTURE','Your patterns','A few useful signals, based only on what you have logged.')}<div class="grid three"><section class="card"><span class="meta">STUDY TIME</span><div class="stat-number">${Math.round(state.sessions.reduce((s,x)=>s+Number(x.minutes),0)/60*10)/10} hrs</div><p class="muted">Across all logged sessions</p></section><section class="card"><span class="meta">SESSIONS</span><div class="stat-number">${state.sessions.length}</div><p class="muted">Every session counts</p></section><section class="card"><span class="meta">UPCOMING DEADLINES</span><div class="stat-number">${allDeadlines().length}</div><p class="muted">${allDeadlines().filter(a=>a.due&&a.due<=today()).length} need attention now</p></section></div><div class="grid two" style="margin-top:18px"><section class="card"><h2>Study in the last 7 days</h2><div class="chart">${days.map((d,i)=>`<div class="bar-wrap"><div class="bar" style="height:${Math.max(4,Math.round(vals[i]/max*130))}px" title="${vals[i]} minutes"></div><small>${fmtDate(d,{weekday:'short'})}</small></div>`).join('')}</div></section><section class="card"><h2>Time by module</h2>${Object.keys(byModule).length?Object.entries(byModule).sort((a,b)=>b[1]-a[1]).map(([name,n])=>`<div class="list-row"><strong>${esc(name)}</strong><span class="tag lime">${n} min</span></div>`).join(''):empty('Not enough information yet','Log a study session to see module patterns.')}</section></div><section class="card" style="margin-top:18px"><h2>A weekly check-in</h2><p class="muted">You logged ${state.sessions.filter(s=>days.includes(s.date)).length} study session(s) this week and ${monthTransactions().filter(t=>t.type==='expense').length} expense(s) this month. ${allDeadlines().length?`${allDeadlines().length} deadline(s) are still open.`:'There are no open deadlines.'} These are observations, not judgments.</p><button class="button small lime" data-action="plan-session">Plan one small session</button></section>`}
function renderSettings(){return `${header('YOUR SPACE','Settings','Keep the app comfortable, private, and in your control.')}<div class="grid two"><section class="card"><div class="settings-block"><h2>Profile & preferences</h2><p>The name and budget you see throughout Aniro.</p><div class="form-grid"><div class="field"><label for="setting-name">Your name</label><input id="setting-name" value="${esc(state.settings.name)}" maxlength="30"></div><div class="field"><label for="setting-budget">Monthly budget (Rs)</label><input id="setting-budget" type="number" min="0" value="${Number(state.settings.budget)}"></div></div><div class="form-actions"><button class="button lime" data-action="save-settings">Save preferences</button></div></div><div class="divider"></div><div class="settings-block"><h3>Low-energy mode</h3><p>Keep your daily view focused on the few things that matter most.</p><button class="button small ghost" data-action="toggle-low-energy">${state.settings.lowEnergy?'Turn off':'Turn on'} low-energy mode</button></div></section><section class="card"><h2>Data and privacy</h2><p class="muted">Your records are stored in this browser on this device. Export a backup regularly, especially before clearing browser data.</p><div class="stack"><button class="button ghost" data-action="export-json">Export JSON backup</button><button class="button ghost" data-action="export-csv">Export CSV files</button><button class="button ghost" data-action="import-json">Import JSON backup</button></div><div class="divider"></div><p class="activity">${state.audit.length} recent changes are available in the local audit history. The most recent change can be undone.</p><button class="button small soft" data-action="undo" ${state.audit.length?'':'disabled'}>Undo last change</button></section></div><div class="section-title"><h2>Google Calendar</h2></div><section class="card"><p class="muted">Add approved study plans to your Google Calendar. To connect, enter a Google OAuth web client ID configured for this site's origin. Aniro only creates, updates, or removes events that it owns.</p><div class="form-grid"><div class="field"><label for="calendar-client">OAuth client ID</label><input id="calendar-client" value="${esc(state.settings.calendarClientId)}" placeholder="...apps.googleusercontent.com"></div><div class="field"><label for="calendar-id">Calendar ID</label><input id="calendar-id" value="${esc(state.settings.calendarId)}" placeholder="primary"></div></div><div class="row-wrap" style="margin-top:16px"><button class="button small ghost" data-action="save-calendar-settings">Save Calendar setup</button><button class="button small lime" data-action="connect-calendar">${googleToken?'Connected for this session':'Connect Google Calendar'}</button>${googleToken?'<button class="button small ghost" data-action="disconnect-calendar">Disconnect</button>':''}</div><p class="activity" style="margin:15px 0 0">Calendar access lasts for this browser session only. You can still download a calendar file from each plan without connecting.</p></section><div class="section-title"><h2>Planned sessions</h2></div><section class="card">${state.plans.length?state.plans.slice().sort((a,b)=>a.start.localeCompare(b.start)).map(p=>`<div class="list-row"><div><strong>${esc(p.title)}</strong><small>${new Date(p.start).toLocaleString()} · ${p.minutes} min ${p.eventId?'· Synced':''}</small></div><div class="row-wrap"><button class="button small ghost" data-action="download-ics" data-id="${p.id}">.ics</button><button class="button small lime" data-action="sync-plan" data-id="${p.id}">${p.eventId?'Update':'Sync'}</button><button class="text-button" data-action="edit-plan" data-id="${p.id}">Edit</button></div></div>`).join(''):empty('No plans yet','Plan a study session from Study or Insights.')}</section>`}
function renderCalendar(){const now=new Date(),month=new Date(now.getFullYear(),now.getMonth()+calendarOffset,1),first=month.getDay(),count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),slots=Math.ceil((first+count)/7)*7;const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const eventsFor=date=>[...state.assignments.filter(a=>a.due===date).map(a=>({kind:'deadline',title:a.title,id:a.id})),...state.plans.filter(p=>iso(new Date(p.start))===date).map(p=>({kind:'plan',title:p.title,id:p.id}))];const selectedEvents=eventsFor(calendarSelected);return `${header('YOUR TIME','Calendar','See deadlines and study plans together. Choose a day to inspect or edit it.',`<button class="button lime" data-action="plan-session">+ Plan session</button>`)}<div class="calendar-toolbar"><div><h2>${month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><span class="meta">${state.assignments.length} DEADLINES · ${state.plans.length} STUDY PLANS</span></div><div class="row-wrap"><button class="button small ghost" data-action="calendar-today">Today</button><button class="icon-button" data-action="calendar-prev" aria-label="Previous month">←</button><button class="icon-button" data-action="calendar-next" aria-label="Next month">→</button></div></div><div class="calendar-layout"><section class="card calendar-main"><div class="calendar-grid calendar-week">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:slots},(_,i)=>{const d=new Date(month.getFullYear(),month.getMonth(),i-first+1),date=iso(d),events=eventsFor(date),other=d.getMonth()!==month.getMonth();return `<button class="calendar-day ${other?'other':''} ${date===today()?'is-today':''} ${date===calendarSelected?'selected':''}" data-date="${date}" aria-label="${d.toDateString()}, ${events.length} item${events.length===1?'':'s'}"><span class="day-number">${d.getDate()}</span>${events.slice(0,2).map(ev=>`<span class="calendar-chip ${ev.kind}">${esc(ev.title)}</span>`).join('')}${events.length>2?`<span class="calendar-more">+${events.length-2} more</span>`:''}</button>`}).join('')}</div></section><aside class="card calendar-detail"><div class="meta">${fmtDate(calendarSelected,{weekday:'long',month:'long',day:'numeric'})}</div><h2 style="margin-top:12px">This day</h2>${selectedEvents.length?selectedEvents.map(ev=>`<div class="list-row"><div><span class="tag ${ev.kind==='plan'?'lime':'warn'}">${ev.kind==='plan'?'Study plan':'Deadline'}</span><strong style="margin-top:8px">${esc(ev.title)}</strong></div><button class="text-button" data-action="${ev.kind==='plan'?'edit-plan':'edit-assignment'}" data-id="${ev.id}">Edit</button></div>`).join(''):empty('A clear day','No deadlines or study plans here yet.')}<button class="button small ghost full" data-action="plan-session" style="margin-top:14px">+ Add study time</button></aside></div>`}
function renderSettingsFull(){return renderSettings().replace('Your records are stored in this browser on this device. Export a backup regularly, especially before clearing browser data.','Your records are stored in the Aniro SQLite database on this computer. Export backups regularly.')+`<div class="section-title"><h2>Account & security</h2></div><div class="grid two"><section class="card"><span class="meta">SIGNED IN AS</span><h2 style="margin-top:12px">${esc(state.settings.name||currentUser?.displayName||'')}</h2><p class="muted">Username: ${esc(currentUser?.username||'')}</p><button class="button ghost" data-action="logout">Sign out</button></section><section class="card"><h2>Change password</h2><p class="muted">Use at least 12 characters. Other signed-in sessions will be closed.</p><div class="stack"><div class="field"><label for="current-password">Current password</label><input id="current-password" type="password" autocomplete="current-password"></div><div class="field"><label for="new-password">New password</label><input id="new-password" type="password" autocomplete="new-password" minlength="12"></div><div class="field"><label for="confirm-password">Confirm new password</label><input id="confirm-password" type="password" autocomplete="new-password" minlength="12"></div><button class="button lime" data-action="change-password">Update password</button></div></section></div>`}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(label,name,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option value="${esc(o[0])}" ${String(value)===String(o[0])?'selected':''}>${esc(o[1])}</option>`).join('')}</select></div>`}
const moduleOpts=()=>[['','General'],...state.modules.map(m=>[m.id,m.name])];
function formModal(title,body,saveAction,id='',dangerAction=''){modal(`<h2 id="dialog-title">${title}</h2><p class="modal-guide">Edit what you need, then select Save. Cancel, ×, or Esc closes this without changing anything.</p><div class="form-grid">${body}</div><div class="form-actions">${dangerAction?`<button type="button" class="button danger" data-action="${dangerAction}" data-id="${id}">Delete</button>`:''}<button type="button" class="button ghost" data-action="close-modal">Cancel</button><button type="button" class="button lime" data-action="${saveAction}" data-id="${id}">Save changes</button></div>`)}
const value=name=>($(`[name="${name}"]`,$('#modal-content'))?.value||'').trim();
function openModule(id){const m=state.modules.find(x=>x.id===id)||{};formModal(id?'Edit module':'Add a module',`${field('Module name','name',m.name,'text','required')}${field('Code','code',m.code)}${selectField('Learning type','type',[['Memory-heavy','Memory-heavy'],['Practice-heavy','Practice-heavy'],['Concept-heavy','Concept-heavy'],['Project-heavy','Project-heavy']],m.type||'Concept-heavy')}${selectField('Confidence','confidence',[1,2,3,4,5].map(n=>[n,`${n} / 5`]),m.confidence||3)}${field('Topics (comma separated)','topics',m.topics||'')}`,'save-module',id,id?'delete-module':'')}
function saveModule(id){const name=value('name');if(!name)return toast('Give the module a name');const data={name,code:value('code'),type:value('type'),confidence:Number(value('confidence')),topics:value('topics')};commit('module',id?'Module updated':'Module added',()=>{if(id)Object.assign(state.modules.find(m=>m.id===id),data);else state.modules.push({id:uid(),...data})});closeModal()}
function openAssignment(id){const a=state.assignments.find(x=>x.id===id)||{};formModal(id?'Edit deadline':'Add assignment or exam',`${field('Title','title',a.title,'text','required')}${selectField('Type','kind',[['Assignment','Assignment'],['Exam','Exam'],['Task','Task']],a.kind||'Assignment')}${selectField('Module','moduleId',moduleOpts(),a.moduleId||'')}${field('Due date','due',a.due||today(),'date')}${selectField('Status','status',[['not started','Not started'],['in progress','In progress'],['submitted','Submitted'],['completed','Completed']],a.status||'not started')}${field('Estimated effort (hours)','effort',a.effort||1,'number','min="0" step="0.5"')}`,'save-assignment',id,id?'delete-assignment':'')}
function saveAssignment(id){const title=value('title');if(!title)return toast('Give the work a title');const data={title,kind:value('kind'),moduleId:value('moduleId'),due:value('due'),status:value('status'),effort:Number(value('effort'))||1};commit('assignment',id?'Deadline updated':'Deadline added',()=>{if(id)Object.assign(state.assignments.find(a=>a.id===id),data);else state.assignments.push({id:uid(),...data})});closeModal()}
const categories=['Food','Transport','Education','Health','Subscriptions','Entertainment','Family','Other'];
function openTransaction(id){const t=state.transactions.find(x=>x.id===id)||{};formModal(id?'Edit transaction':'Log a transaction',`${selectField('Type','type',[['expense','Expense'],['income','Income']],t.type||'expense')}${field('Amount (Rs)','amount',t.amount||'','number','min="0.01" step="0.01" required')}${selectField('Category','category',categories.map(c=>[c,c]),t.category||'Food')}${field('Date','date',t.date||today(),'date')}${field('Note','note',t.note||'')}`,'save-transaction',id,id?'delete-transaction':'')}
function saveTransaction(id){const amount=Number(value('amount'));if(!(amount>0))return toast('Enter an amount greater than zero');const data={type:value('type'),amount,category:value('category'),date:value('date')||today(),note:value('note')};commit('transaction',id?'Transaction updated':'Transaction logged',()=>{if(id)Object.assign(state.transactions.find(t=>t.id===id),data);else state.transactions.push({id:uid(),...data})});closeModal()}
function openHealth(id){const h=state.health.find(x=>x.id===id)||{};formModal(id?'Edit note':'Add a wellbeing note',`${selectField('What would you like to track?','kind',['Sleep','Mood','Energy','Meal','Water','Movement','Stress','Other'].map(c=>[c,c]),h.kind||'Sleep')}${field('Value','value',h.value||'','text','placeholder="e.g. 7 hours or okay"')}${field('Date','date',h.date||today(),'date')}${field('Notes','note',h.note||'')}`,'save-health',id,id?'delete-health':'')}
function saveHealth(id){const data={kind:value('kind'),value:value('value'),date:value('date')||today(),note:value('note')};if(!data.value&&!data.note)return toast('Add a value or note');commit('health',id?'Wellbeing note updated':'Wellbeing note added',()=>{if(id)Object.assign(state.health.find(h=>h.id===id),data);else state.health.push({id:uid(),...data})});closeModal()}
function openHabit(id){const h=state.habits.find(x=>x.id===id)||{};formModal(id?'Edit habit':'Add a small habit',`${field('Habit name','name',h.name||'','text','required')}${field('Optional cue / anchor','cue',h.cue||'','text','placeholder="After I make tea..."')}`,'save-habit',id,id?'delete-habit':'')}
function saveHabit(id){const name=value('name');if(!name)return toast('Name your habit');const data={name,cue:value('cue')};commit('habit',id?'Habit updated':'Habit added',()=>{if(id)Object.assign(state.habits.find(h=>h.id===id),data);else state.habits.push({id:uid(),...data})});closeModal()}
function openPlan(id){const p=state.plans.find(x=>x.id===id)||{};const next=new Date();next.setMinutes(0,0,0);next.setHours(next.getHours()+1);const initial=p.start?p.start.slice(0,16):`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}T${String(next.getHours()).padStart(2,'0')}:00`;formModal(id?'Edit study plan':'Plan a study session',`${field('Session title','title',p.title||'Focus session','text','required')}${selectField('Module','moduleId',moduleOpts(),p.moduleId||'')}${field('Start','start',initial,'datetime-local','required')}${field('Duration (minutes)','minutes',p.minutes||25,'number','min="5" max="240" required')}`,'save-plan',id,id?'delete-plan':'')}
function savePlan(id){const title=value('title'),start=value('start'),minutes=Number(value('minutes'));if(!title||!start||!(minutes>=5&&minutes<=240))return toast('Check the title, time, and duration');const data={title,start:new Date(start).toISOString(),minutes,moduleId:value('moduleId')};commit('plan',id?'Plan updated':'Study session planned',()=>{if(id)Object.assign(state.plans.find(p=>p.id===id),data);else state.plans.push({id:uid(),...data,eventId:null})});closeModal()}
function confirmDelete(kind,id){const map={module:'modules',assignment:'assignments',transaction:'transactions',health:'health',habit:'habits',plan:'plans'};const arr=map[kind];if(!arr)return;const target=state[arr].find(x=>x.id===id);if(!target)return;modal(`<h2>Delete ${kind}?</h2><p>This removes <strong>${esc(target.title||target.name||target.note||target.kind||'this record')}</strong> from this device. The last change can be undone.</p>${kind==='plan'&&target.eventId?'<p class="notice note-warning">This plan has a synced Google event. Remove that event separately before deleting the local plan.</p>':''}<div class="form-actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button type="button" class="button danger" data-action="confirm-delete" data-kind="${kind}" data-id="${id}">Delete ${kind}</button></div>`)}
function performDelete(kind,id){const map={module:'modules',assignment:'assignments',transaction:'transactions',health:'health',habit:'habits',plan:'plans'};const arr=map[kind];if(kind==='plan'&&state.plans.find(p=>p.id===id)?.eventId)return toast('Remove the synced event first');commit(kind,`${kind[0].toUpperCase()+kind.slice(1)} deleted`,()=>{state[arr]=state[arr].filter(x=>x.id!==id);if(kind==='habit')state.checkins=state.checkins.filter(c=>c.habitId!==id)});if(kind==='habit'&&selectedHabitId===id)selectedHabitId='';closeModal()}
function openTimer(){const opts=moduleOpts();modal(`<h2>Focus session</h2><p class="muted">Small sessions count. Choose a module and begin when you are ready.</p>${selectField('Module','timerModule',opts,timer.moduleId)}<div class="timer-ring"><div id="timer-readout" class="timer-display">${clock(timer.seconds)}</div></div><div class="row-wrap" style="justify-content:center"><button type="button" class="button small ghost" data-action="timer-duration" data-minutes="10">10 min</button><button type="button" class="button small ghost" data-action="timer-duration" data-minutes="25">25 min</button><button type="button" class="button small ghost" data-action="timer-duration" data-minutes="45">45 min</button></div><div class="form-actions" style="justify-content:center"><button type="button" class="button lime" data-action="timer-toggle">${timer.running?'Pause':'Start'}</button><button type="button" class="button ghost" data-action="timer-save">Save session</button></div>`)}
function clock(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function tickTimer(){if(!timer.running)return;timer.seconds=Math.max(0,timer.seconds-1);if($('#timer-readout'))$('#timer-readout').textContent=clock(timer.seconds);if(timer.seconds===0){timer.running=false;clearInterval(timerInterval);toast('Focus session complete. Save it when ready.');if(Notification.permission==='granted')new Notification('Aniro',{body:'Focus session complete. Nice work.'})}}
function timerToggle(){timer.moduleId=value('timerModule');timer.running=!timer.running;if(timer.running){if(!timer.started)timer.started=Date.now();timerInterval=setInterval(tickTimer,1000)}else clearInterval(timerInterval);const btn=$('[data-action="timer-toggle"]');if(btn)btn.textContent=timer.running?'Pause':'Resume'}
function timerSave(){timer.moduleId=value('timerModule');const elapsed=timer.started?Math.round((Date.now()-timer.started)/60000):0;const planned=Number(timer.mode)||25;const minutes=Math.max(1,elapsed||planned-Math.ceil(timer.seconds/60));commit('session','Study session saved',()=>state.sessions.push({id:uid(),moduleId:timer.moduleId,date:today(),minutes,note:'Focus timer'}));timer.running=false;clearInterval(timerInterval);timer={seconds:25*60,running:false,started:null,mode:'focus',moduleId:''};closeModal()}
let pendingCapture=null;
async function reviewCapture(mode='local'){const text=$('#capture-text')?.value.trim();if(!text)return toast('Write something first');if(text.length>5000)return toast('Keep your note under 5000 characters');let proposals,fallbackMessage='';if(mode==='ai'){const button=$('[data-action="parse-capture-ai"]');button.disabled=true;button.textContent='Asking AI…';try{const result=await api('/api/ai/parse','POST',{text,today:today()});proposals=result.proposals}catch(error){fallbackMessage=`${error.message} Showing local suggestions instead.`;proposals=parseCapture(text,state.modules);mode='local'}finally{button.disabled=false;button.textContent='Review with AI'}}else proposals=parseCapture(text,state.modules);pendingCapture={text,proposals,mode,fallbackMessage};renderProposals()}
function renderProposals(){const area=$('#proposal-area');if(!area||!pendingCapture)return;const proposals=pendingCapture.proposals;area.innerHTML=`<div class="section-title"><h2>Review suggestions</h2><span class="meta">${proposals.length} FOUND · ${pendingCapture.mode==='ai'?'AI':'LOCAL'}</span></div>${pendingCapture.fallbackMessage?`<p class="notice note-warning" role="status">${esc(pendingCapture.fallbackMessage)}</p>`:''}${proposals.length?`<p class="muted">Edit any detail. Uncheck anything you do not want to save.</p><div class="record-list">${proposals.map((p,i)=>proposalCard(p,i)).join('')}</div>`:`<div class="notice">Aniro could not safely identify a structured update. You can still save this as a note in your inbox.</div>`}<div class="row-wrap" style="margin:20px 0 5px"><button class="button lime" data-action="approve-capture">Save reviewed items</button><button class="button ghost" data-action="cancel-capture">Cancel</button></div>`;area.scrollIntoView({behavior:'smooth',block:'start'})}
function proposalCard(p,i){const pre=`proposal-${i}`;let controls='';if(p.type==='transaction')controls=`${field('Amount (Rs)',`${pre}-amount`,p.amount,'number','min="0.01" step="0.01"')}${selectField('Category',`${pre}-category`,categories.map(c=>[c,c]),p.category)}${selectField('Type',`${pre}-transactionType`,[['expense','Expense'],['income','Income']],p.transactionType)}${field('Date',`${pre}-date`,p.date,'date')}`;if(p.type==='session')controls=`${field('Minutes',`${pre}-minutes`,p.minutes,'number','min="1"')}${selectField('Module',`${pre}-moduleId`,moduleOpts(),p.moduleId)}${field('Date',`${pre}-date`,p.date,'date')}`;if(p.type==='assignment')controls=`${field('Title',`${pre}-title`,p.title)}${selectField('Module',`${pre}-moduleId`,moduleOpts(),p.moduleId)}${field('Due date',`${pre}-due`,p.due,'date')}${selectField('Type',`${pre}-kind`,[['Assignment','Assignment'],['Exam','Exam']],p.kind)}`;if(p.type==='health')controls=`${selectField('Type',`${pre}-kind`,[['Sleep','Sleep'],['Mood','Mood'],['Meal','Meal'],['Other','Other']],p.kind)}${field('Value',`${pre}-value`,p.value)}${field('Date',`${pre}-date`,p.date,'date')}`;return `<section class="suggestion selected"><div class="suggestion-head"><div class="row-wrap"><input class="check" type="checkbox" id="${pre}-selected" checked><label for="${pre}-selected" style="color:var(--ink);font-weight:700;text-transform:capitalize">${esc(p.type==='session'?'Study session':p.type)}</label></div><span class="tag ${p.confidence==='low'?'warn':'lime'}">${esc(p.confidence)} confidence</span></div><div class="suggestion-source">From: “${esc(p.source)}”</div><div class="form-grid">${controls}</div></section>`}
function approveCapture(){if(!pendingCapture)return;const {text,proposals}=pendingCapture;const approved=[];for(let i=0;i<proposals.length;i++){if(!$(`#proposal-${i}-selected`)?.checked)continue;const p=proposals[i],get=n=>$(`[name="proposal-${i}-${n}"]`)?.value||'';if(p.type==='transaction'){if(!(Number(get('amount'))>0))return toast('Transaction amount must be greater than zero');approved.push({type:'transaction',record:{id:uid(),type:get('transactionType'),amount:Number(get('amount')),category:get('category'),date:get('date')||today(),note:text.slice(0,80)}})}if(p.type==='session'){if(!(Number(get('minutes'))>0))return toast('Study minutes must be greater than zero');approved.push({type:'session',record:{id:uid(),minutes:Number(get('minutes')),moduleId:get('moduleId'),date:get('date')||today(),note:'From inbox'}})}if(p.type==='assignment'){if(!get('title').trim())return toast('Give the assignment a title');approved.push({type:'assignment',record:{id:uid(),title:get('title').trim(),moduleId:get('moduleId'),due:get('due'),kind:get('kind'),status:'not started',effort:1}})}if(p.type==='health')approved.push({type:'health',record:{id:uid(),kind:get('kind'),value:get('value'),date:get('date')||today(),note:''}})}commit('capture',`${approved.length} update${approved.length===1?'':'s'} saved`,()=>{state.messages.unshift({id:uid(),text,date:today(),status:'reviewed',approved:approved.length});for(const a of approved)state[{transaction:'transactions',session:'sessions',assignment:'assignments',health:'health'}[a.type]].push(a.record);state.draftText='' });pendingCapture=null}
function download(filename,content,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportJson(){download(`aniro-backup-${today()}.json`,JSON.stringify({...state,audit:[]},null,2),'application/json')}
function exportCsv(){for(const name of ['modules','assignments','sessions','transactions','health','habits','checkins','plans']){const rows=state[name];if(!rows.length)continue;const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];const q=v=>`"${String(v??'').replaceAll('"','""')}"`;download(`aniro-${name}-${today()}.csv`,[keys.join(','),...rows.map(r=>keys.map(k=>q(r[k])).join(','))].join('\r\n'),'text/csv')}}
async function importJson(file){if(!file)return;try{const data=JSON.parse(await file.text());if(!data||data.version!==1||!Array.isArray(data.modules)||!Array.isArray(data.assignments)||!Array.isArray(data.transactions))throw Error('This is not an Aniro backup');modal(`<h2>Restore backup?</h2><p>This will replace the current records on this device with the data in <strong>${esc(file.name)}</strong>.</p><div class="form-actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button type="button" class="button lime" data-action="confirm-import">Restore</button></div>`);window.__aniroImport=data}catch(e){toast(e.message)}}
function confirmImport(){state={...clone(defaults),...window.__aniroImport,settings:{...defaults.settings,...window.__aniroImport.settings},audit:[]};delete window.__aniroImport;persist();closeModal();render();toast('Backup restored')}
function icsDate(iso){return new Date(iso).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}
function downloadIcs(id){const p=state.plans.find(x=>x.id===id);if(!p)return;const end=new Date(new Date(p.start).getTime()+p.minutes*60000).toISOString();const safe=p.title.replace(/[\\,;]/g,' ').replace(/\n/g,' ');const text=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Aniro//Study Plan//EN\r\nBEGIN:VEVENT\r\nUID:${p.id}@aniro.local\r\nDTSTAMP:${icsDate(new Date().toISOString())}\r\nDTSTART:${icsDate(p.start)}\r\nDTEND:${icsDate(end)}\r\nSUMMARY:${safe}\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`;download(`aniro-study-${p.id.slice(0,8)}.ics`,text,'text/calendar')}
function loadGoogleScript(){return new Promise((resolve,reject)=>{if(window.google?.accounts?.oauth2)return resolve();const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=()=>reject(Error('Google sign-in could not load'));document.head.append(script)})}
async function connectCalendar(){if(!state.settings.calendarClientId)return toast('Add your OAuth client ID in Settings first');try{await loadGoogleScript();googleTokenClient=google.accounts.oauth2.initTokenClient({client_id:state.settings.calendarClientId,scope:'https://www.googleapis.com/auth/calendar.events',callback:response=>{if(response.error)return toast(`Google connection failed: ${response.error}`);googleToken=response.access_token;render();toast('Google Calendar connected for this session')}});googleTokenClient.requestAccessToken({prompt:'consent'})}catch(e){toast(e.message)}}
async function googleRequest(path,method='GET',body){if(!googleToken)throw Error('Connect Google Calendar first');const res=await fetch(`https://www.googleapis.com/calendar/v3/${path}`,{method,headers:{Authorization:`Bearer ${googleToken}`,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(res.status===401){googleToken=null;throw Error('Calendar session expired. Connect again.')}if(!res.ok){const error=await res.json().catch(()=>({}));throw Error(error.error?.message||`Google Calendar returned ${res.status}`)}return res.status===204?null:res.json()}
function calendarPath(p){return `calendars/${encodeURIComponent(p.calendarId||state.settings.calendarId||'primary')}/events${p.eventId?`/${encodeURIComponent(p.eventId)}`:''}`}
function previewSync(id){const p=state.plans.find(x=>x.id===id);if(!p)return;modal(`<h2>${p.eventId?'Update':'Add to'} Google Calendar?</h2><div class="calendar-preview"><strong>${esc(p.title)}</strong><p style="margin:8px 0 0">${new Date(p.start).toLocaleString()} · ${p.minutes} min<br>Calendar: ${esc(p.calendarId||state.settings.calendarId)}</p></div><p class="muted">Only this approved Aniro study event will be ${p.eventId?'updated':'created'}.</p><div class="form-actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button type="button" class="button lime" data-action="confirm-sync" data-id="${id}">Confirm ${p.eventId?'update':'add'}</button></div>${p.eventId?`<button type="button" class="text-button" data-action="preview-remove-event" data-id="${id}">Remove this Google event</button>`:''}`)}
async function syncPlan(id){const p=state.plans.find(x=>x.id===id);if(!p)return;const end=new Date(new Date(p.start).getTime()+p.minutes*60000).toISOString();try{const result=await googleRequest(calendarPath(p),p.eventId?'PUT':'POST',{summary:p.title,description:`Aniro study session${p.moduleId?` · ${moduleName(p.moduleId)}`:''}`,start:{dateTime:p.start},end:{dateTime:end},extendedProperties:{private:{aniroPlanId:p.id}}});commit('calendar','Calendar event synced',()=>{p.eventId=result.id;p.calendarId=p.calendarId||state.settings.calendarId});closeModal()}catch(e){toast(e.message)}}
function previewRemoveEvent(id){const p=state.plans.find(x=>x.id===id);if(!p?.eventId)return;modal(`<h2>Remove Google event?</h2><p>This will remove the Aniro-created event for <strong>${esc(p.title)}</strong> from Google Calendar. The local study plan will remain.</p><div class="form-actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button type="button" class="button danger" data-action="confirm-remove-event" data-id="${id}">Remove event</button></div>`)}
async function removeEvent(id){const p=state.plans.find(x=>x.id===id);if(!p?.eventId)return;try{await googleRequest(calendarPath(p),'DELETE');commit('calendar','Google event removed',()=>{p.eventId=null;p.calendarId=null});closeModal()}catch(e){toast(e.message)}}
function updateOnline(){const badge=$('#offline-badge');if(badge)badge.hidden=navigator.onLine}
document.addEventListener('click',async e=>{const pageButton=e.target.closest('[data-page]');if(pageButton){closeModal();setPage(pageButton.dataset.page);return}const button=e.target.closest('[data-action]');if(!button)return;e.preventDefault();const action=button.dataset.action,id=button.dataset.id;switch(action){case'close-modal':closeModal();break;case'undo':undo();closeModal();break;case'parse-capture':reviewCapture();break;case'cancel-capture':pendingCapture=null;$('#proposal-area').innerHTML='';break;case'approve-capture':approveCapture();break;case'add-module':openModule();break;case'edit-module':openModule(id);break;case'save-module':saveModule(id);break;case'add-assignment':openAssignment();break;case'edit-assignment':openAssignment(id);break;case'save-assignment':saveAssignment(id);break;case'complete-assignment':commit('assignment','Assignment completed',()=>state.assignments.find(a=>a.id===id).status='completed');break;case'add-transaction':openTransaction();break;case'edit-transaction':openTransaction(id);break;case'save-transaction':saveTransaction(id);break;case'add-health':openHealth();break;case'edit-health':openHealth(id);break;case'save-health':saveHealth(id);break;case'add-habit':openHabit();break;case'edit-habit':openHabit(id);break;case'save-habit':saveHabit(id);break;case'plan-session':openPlan();break;case'edit-plan':openPlan(id);break;case'save-plan':savePlan(id);break;case'open-timer':openTimer();break;case'timer-duration':timer.running=false;clearInterval(timerInterval);timer.seconds=Number(button.dataset.minutes)*60;timer.mode=Number(button.dataset.minutes);timer.started=null;$('#timer-readout').textContent=clock(timer.seconds);$('[data-action="timer-toggle"]').textContent='Start';break;case'timer-toggle':timerToggle();break;case'timer-save':timerSave();break;case'edit-budget':setPage('settings');$('#setting-budget')?.focus();break;case'save-settings':commit('settings','Preferences saved',()=>{state.settings.name=$('#setting-name').value.trim()||'there';state.settings.budget=Math.max(0,Number($('#setting-budget').value)||0)});break;case'toggle-low-energy':commit('settings','Low-energy mode changed',()=>state.settings.lowEnergy=!state.settings.lowEnergy);break;case'save-calendar-settings':commit('settings','Calendar setup saved',()=>{state.settings.calendarClientId=$('#calendar-client').value.trim();state.settings.calendarId=$('#calendar-id').value.trim()||'primary'});break;case'connect-calendar':connectCalendar();break;case'disconnect-calendar':googleToken=null;googleTokenClient=null;render();toast('Calendar disconnected');break;case'sync-plan':previewSync(id);break;case'confirm-sync':syncPlan(id);break;case'preview-remove-event':previewRemoveEvent(id);break;case'confirm-remove-event':removeEvent(id);break;case'download-ics':downloadIcs(id);break;case'export-json':exportJson();break;case'export-csv':exportCsv();break;case'import-json':$('#import-file').click();break;case'confirm-import':confirmImport();break;case'confirm-delete':performDelete(button.dataset.kind,id);break;default:if(action.startsWith('delete-'))confirmDelete(action.slice(7),id)}});
document.addEventListener('input',e=>{if(e.target.id==='capture-text'){state.draftText=e.target.value;persist()}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="parse-capture-ai"]'))reviewCapture('ai')});
document.addEventListener('submit',e=>{if(e.target.id!=='quick-habit-form')return;e.preventDefault();const name=$('#quick-habit-name')?.value.trim();if(!name)return;const id=uid();selectedHabitId=id;commit('habit',`Habit added: ${name}`,()=>state.habits.push({id,name,cue:''}));$('#quick-habit-name')?.focus()});
document.addEventListener('change',e=>{if(e.target.id==='habit-map-select'){selectedHabitId=e.target.value;render()}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action="toggle-habit-date"]');if(!button)return;const {id,date}=button.dataset;if(!state.habits.some(h=>h.id===id)||!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>today())return;const exists=state.checkins.some(c=>c.habitId===id&&c.date===date);selectedHabitId=id;commit('habit',exists?'Check-in removed':'Habit checked in',()=>{state.checkins=state.checkins.filter(c=>!(c.habitId===id&&c.date===date));if(!exists)state.checkins.push({id:uid(),habitId:id,date})});$$('[data-action="toggle-habit-date"]').find(next=>next.dataset.id===id&&next.dataset.date===date)?.focus()});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action="suggest-plan"]');if(!button)return;const m=state.modules.find(x=>x.id===button.dataset.id);if(!m)return;openPlan();$('[name="moduleId"]',$('#modal-content')).value=m.id;$('[name="title"]',$('#modal-content')).value=`${m.name}: ${strategy(m.type)}`;$('[name="minutes"]',$('#modal-content')).value=Number(m.confidence)<=2?15:25});
document.addEventListener('click',e=>{const dateButton=e.target.closest('[data-date]');if(dateButton){calendarSelected=dateButton.dataset.date;render();return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='calendar-prev'){calendarOffset--;render()}if(action==='calendar-next'){calendarOffset++;render()}if(action==='calendar-today'){calendarOffset=0;calendarSelected=today();render()}});
document.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();const form=e.target,button=$('button[type="submit"]',form);button.disabled=true;try{const data={username:$('#auth-username').value.trim(),password:$('#auth-password').value};if(registrationOpen)data.displayName=$('#auth-name').value.trim();await api(registrationOpen?'/api/register':'/api/login','POST',data);await boot();toast(registrationOpen?'Account created':'Signed in')}catch(error){renderAuth(error.message)}finally{button.disabled=false}});
document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='logout'){await saveQueue;try{await api('/api/logout','POST',{});authenticated=false;currentUser=null;state=clone(defaults);revision=0;registrationOpen=false;saveQueue=Promise.resolve();googleToken=null;renderAuth();toast('Signed out')}catch(error){toast(error.message)}}if(action==='change-password'){const currentPassword=$('#current-password')?.value||'',newPassword=$('#new-password')?.value||'',confirmation=$('#confirm-password')?.value||'';if(newPassword!==confirmation)return toast('New passwords do not match');try{await api('/api/password','POST',{currentPassword,newPassword});$('#current-password').value='';$('#new-password').value='';$('#confirm-password').value='';toast('Password updated. Other sessions were signed out.')}catch(error){toast(error.message)}}});
$('#import-file').addEventListener('change',e=>{importJson(e.target.files?.[0]);e.target.value=''});
$('#quick-capture').addEventListener('click',()=>{setPage('inbox');$('#capture-text')?.focus()});
$('#menu-button').addEventListener('click',()=>modal(`<h2>Go to</h2><div class="stack">${nav.map(([id,label])=>`<button type="button" class="button ghost full" data-page="${id}">${label}</button>`).join('')}</div>`));
window.addEventListener('online',updateOnline);window.addEventListener('offline',updateOnline);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
boot();
})();
